      read_client: Timekeeping::EntryApiClient.new(base_url: import_base_url)
    )
    key = Digest::UUID.uuid_v5(Timekeeping::EntryWriteClient::IDEMPOTENCY_NAMESPACE, "tenant-import-row-1")

    entry = with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
      gateway.import(
        user: import_row_user, project: import_project,
        attributes: { duration: 60, work_date: Date.current, note: "Harvest row", bill_status: "unbilled",
                      source: "import", source_metadata: { tool: "harvest" } },
        idempotency_key: key, expected_generation: 2
      )
    end

    expect(import_fake.requests.size).to eq(1)
    request = import_fake.requests.first
    expect(request[:path]).to eq("/v1/companies/#{import_company.id}/entries")
    expect(request[:body]["user_id"]).to eq(import_row_user.id)
    expect(request[:body]["project_id"]).to eq(import_project.id)
    expect(entry.company_id).to eq(import_company.id)
    expect(entry.user_id).to eq(import_row_user.id)
    expect(entry.user_id).not_to eq(import_actor.id)
  end
end

RSpec.describe Timekeeping::Gateway do
  # "A billed row is always one write that carries its final bill status, so no refusal can leave it unbilled."
  # The update to billed raises after the create has run, so a create that commits on its own leaves an unbilled entry.
  it "leaves no entry when the billing step of a legacy billed import fails" do
    company = create(:company)
    project = create(:project, billable: true, client: create(:client, company:))
    admin = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user: admin)
    context = Timekeeping::WriteContext.new(company:, actor: admin, actor_kind: "import", request_id: SecureRandom.uuid)
    gateway = described_class.new(context:)
    allow_any_instance_of(TimesheetEntry).to receive(:update!).and_raise(ActiveRecord::RecordInvalid.new(TimesheetEntry.new))

    expect do
      gateway.import(
        user: admin, project:,
        attributes: { duration: 60, work_date: Date.new(2026, 1, 5), note: "billed row", bill_status: "billed",
                      source: "import", source_metadata: { tool: "harvest" } },
        idempotency_key: Digest::UUID.uuid_v5(Digest::UUID::OID_NAMESPACE, "legacy-billed-row"),
        expected_generation: TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).generation
      )
    end.to raise_error(ActiveRecord::RecordInvalid)

    expect(TimesheetEntry.where(project:).count).to eq(0)
  end
end

RSpec.describe Timekeeping::Gateway do
  # "Forwarded writes use an `Idempotency-Key` built from the data import id and a digest of the row, so rerunning a failed import does not duplicate rows it already forwarded."
  # One request id serves every row of a job, so a key taken from the request id would make the
  # second distinct row a reused key with a different body; the caller's key must be sent instead.
  it "replays a forwarded billed import sent twice under one Idempotency-Key as one entry and keeps two keys apart" do
    company = create(:company)
    project = create(:project, billable: true, client: create(:client, company:))
    admin = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user: admin)
    admin.add_role :admin, company
    base_url = "http://timekeeping.test"
    fake = TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key)
    route_timekeeping_to_fake(fake, base_url:)
    TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).update_columns(owner: "timekeeping", generation: 2)
    fake.generation = 2
    fake.register_company(id: company.id, edit_days: company.timesheet_edit_days)
    fake.register_user(id: admin.id, company_id: company.id, role: "admin")
    fake.register_project(id: project.id, company_id: company.id)
    context = Timekeeping::WriteContext.new(company:, actor: admin, actor_kind: "import", request_id: SecureRandom.uuid)
    gateway = described_class.new(
      context:, write_client: Timekeeping::EntryWriteClient.new(base_url:),
      read_client: Timekeeping::EntryApiClient.new(base_url:)
    )
    attributes = { duration: 60, work_date: Date.new(2026, 1, 5), note: "billed row", bill_status: "billed",
                   source: "import", source_metadata: { tool: "harvest" } }
    row_key = Digest::UUID.uuid_v5(Digest::UUID::OID_NAMESPACE, "import-1/row-2")
    other_row_key = Digest::UUID.uuid_v5(Digest::UUID::OID_NAMESPACE, "import-1/row-3")

    first, replayed, other = with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
      [row_key, row_key, other_row_key].map do |key|
        gateway.import(user: admin, project:, attributes:, idempotency_key: key, expected_generation: 2)
      end
    end

    expect(replayed.id).to eq(first.id)
    expect(other.id).not_to eq(first.id)
    posts = fake.requests.select { |request| request[:method] == "POST" }
    expect(posts.map { |request| request[:headers]["Idempotency-Key"] }).to eq([row_key, row_key, other_row_key])
    expect(posts.map { |request| request[:body]["bill_status"] }).to eq(%w[billed billed billed])
    expect(fake.requests.count { |request| request[:method] == "PATCH" }).to eq(0)
  end
end

RSpec.describe Timekeeping::Gateway do
  let(:gi_company) { create(:company) }
  let(:gi_admin) do
    create(:user, current_workspace_id: gi_company.id).tap do |user|
      create(:employment, company: gi_company, user:)
      user.add_role :admin, gi_company
    end
  end
  let(:gi_project) { create(:project, billable: true, client: create(:client, company: gi_company)) }
  let(:gi_context) do
    Timekeeping::WriteContext.new(company: gi_company, actor: gi_admin, actor_kind: "import", request_id: SecureRandom.uuid)
  end
  let(:gi_attributes) do
    { duration: 60, work_date: Date.new(2026, 1, 5), note: "harvest row", bill_status: "billed",
      source: "import", source_metadata: { tool: "harvest" } }
  end
  let(:gi_generation) { TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).generation }

  it "stores a legacy billed import as one billed entry that keeps the import source" do
    entry = described_class.new(context: gi_context).import(
      user: gi_admin, project: gi_project, attributes: gi_attributes,
      idempotency_key: SecureRandom.uuid, expected_generation: gi_generation
    )

    expect(TimesheetEntry.where(project: gi_project).count).to eq(1)
    expect(entry.reload).to have_attributes(bill_status: "billed", source: "import", user_id: gi_admin.id)
    expect(entry.source_metadata).to eq("tool" => "harvest")
  end

  it "refuses an import while a handoff is in progress and writes nothing" do
    TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).update_columns(handoff_step: "close_admission")

    expect do
      described_class.new(context: gi_context).import(
        user: gi_admin, project: gi_project, attributes: gi_attributes,
        idempotency_key: SecureRandom.uuid, expected_generation: gi_generation
      )
    end.to raise_error(Timekeeping::Gateway::OwnershipMoving)
    expect(TimesheetEntry.where(project: gi_project)).not_to exist
  end

  it "refuses a forwarded import with an invalid duration before anything is sent" do
    base_url = "http://timekeeping.test"
    fake = TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key)
    route_timekeeping_to_fake(fake, base_url:)
    TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).update_columns(owner: "timekeeping", generation: 2)
    gateway = described_class.new(
      context: gi_context, write_client: Timekeeping::EntryWriteClient.new(base_url:),
      read_client: Timekeeping::EntryApiClient.new(base_url:)
    )

    expect do
      gateway.import(
        user: gi_admin, project: gi_project, attributes: gi_attributes.merge(duration: -5),
        idempotency_key: SecureRandom.uuid, expected_generation: 2
      )
    end.to raise_error(ActiveRecord::RecordInvalid)
    expect(fake.requests).to be_empty
  end
end
